import{_ as i,C as a,o as l,c as s,j as t,a as e,E as o,a5 as r}from"./chunks/framework.BYIUCCsM.js";const f=JSON.parse('{"title":"侧栏导航","description":"","frontmatter":{},"headers":[],"relativePath":"components/side-nav.md","filePath":"components/side-nav.md","lastUpdated":1787598366000}'),h={name:"components/side-nav.md"},p={id:"侧栏导航",tabindex:"-1"};function u(b,d,g,x,v,P){const n=a("Badge"),c=a("XhDemo");return l(),s("div",null,[t("h1",p,[d[0]||(d[0]=e("侧栏导航 ",-1)),o(n,{type:"info",text:"side-nav"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#侧栏导航","aria-label":'Permalink to "侧栏导航 <Badge type="info" text="side-nav" />"'},"​",-1))]),d[3]||(d[3]=r('<p>后台侧边那棵导航树：分支可展开，选中落在叶子上并一路点亮祖先枝。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>管理后台、控制台的主导航，层级两到三层。</li><li>侧栏需要折叠成图标栏，且折叠后仍要能进到子级。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>导航只有一层：用一列链接就够。</li><li>是内容树而不是导航树（文件、组织架构）：用<a href="./tree">树</a>。</li><li>顶部横向导航：用<a href="./navigation-menu">导航菜单</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>collection</code> 是层级与文本的唯一事实源。</li><li><code>accordion</code> 让同层只开一枝；不开即可多开。</li><li>折叠成图标栏时内嵌展开整体收起、文字由皮肤藏掉；顶层分支换装浮层弹出，悬停 / 点按 / 右方向键在旁侧弹出子级面板，面板内选中即落值收起。</li><li>方向键上下走行、左右管层级。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>管理后台侧栏：分支内嵌展开（可多开）、选中落在叶子上并一路点亮祖先枝，方向键上下走行、左右管层级</p>',10)),o(c,{src:"side-nav/01-basic"}),d[4]||(d[4]=t("h3",{id:"手风琴与折叠",tabindex:"-1"},[e("手风琴与折叠 "),t("a",{class:"header-anchor",href:"#手风琴与折叠","aria-label":'Permalink to "手风琴与折叠"'},"​")],-1)),d[5]||(d[5]=t("p",null,"accordion 让同层只开一枝；collapsed 折叠成图标栏（内嵌展开整体收起，文字部件整个隐藏只剩图标），折叠态下悬停/点按/右方向键在旁侧弹出子级面板，面板内选中即落值收起；collapsedPopout 设为 false 可关掉弹出",-1)),o(c,{src:"side-nav/02-accordion-collapsed"}),d[6]||(d[6]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-side-nav&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSideNavBranch</code> <code>XhSideNavBranchContent</code> <code>XhSideNavBranchIndicator</code> <code>XhSideNavBranchText</code> <code>XhSideNavBranchTrigger</code> <code>XhSideNavGroup</code> <code>XhSideNavGroupLabel</code> <code>XhSideNavItem</code> <code>XhSideNavLink</code> <code>XhSideNavLinkText</code> <code>XhSideNavList</code> <code>XhSideNavRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSideNav</code></td></tr><tr><td>状态机</td><td><code>sideNavMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/side-nav.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;side-nav&quot;</code>：<strong><code>root</code></strong> · <strong><code>list</code></strong> · <strong><code>item</code></strong> · <code>group</code> · <code>group-label</code> · <code>branch</code> · <code>branch-trigger</code> · <code>branch-text</code> · <code>branch-indicator</code> · <code>positioner</code> · <code>branch-content</code> · <strong><code>link</code></strong> · <code>link-text</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>SideNavNode[]</code></td><td></td><td>入口树，层级与文本的唯一事实源。缺省为空。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中的叶子（单选）。给定即受控：cell 直读 prop，写只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td><td>展开集合。给定即受控，语义同上。</td></tr><tr><td><code>defaultExpandedValue</code></td><td><code>string[]</code></td><td></td><td></td></tr><tr><td><code>accordion</code></td><td><code>boolean</code></td><td></td><td>同层手风琴：展开一枝时收起同层其余分支，默认 false（可多开）。</td></tr><tr><td><code>collapsed</code></td><td><code>boolean</code></td><td></td><td>折叠成图标栏：内嵌展开整体收起、文字由皮肤藏掉，只剩图标一列。 顶层分支换装浮层弹出：悬停/点按/右方向键在旁侧弹出子级面板。</td></tr><tr><td><code>collapsedPopout</code></td><td><code>boolean</code></td><td></td><td>折叠态下顶层分支是否弹出子级面板，默认 true；关掉即回到纯图标栏。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整个侧栏禁用。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>上下键走到首尾是否回绕，默认 false。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只对调左右方向键的「展开/收起」语义。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;SideNavTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: SideNavValueChangeDetails) =&gt; void</code></td><td></td><td>选中意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onExpandedChange</code></td><td><code>(details: SideNavExpandedChangeDetails) =&gt; void</code></td><td></td><td>展开集合变化意图回调；语义同上。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>SideNavValueChangeDetails</code></td><td>选中变化；detail 为 <code>{ value: string | null }</code></td></tr><tr><td><code>expanded-change</code></td><td><code>SideNavExpandedChangeDetails</code></td><td>展开集合变化；detail 为 <code>{ value: string[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSideNavRoot</code></td><td><code>default</code></td><td><code>SideNavRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>branch</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>popout-positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>popout</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>LINK.SELECT</code> · <code>EXPANDED.SET</code> · <code>BRANCH.EXPAND</code> · <code>BRANCH.COLLAPSE</code> · <code>BRANCH.TOGGLE</code> · <code>NODE.FOCUS</code> · <code>FOCUS.CLEAR</code> · <code>POPOUT.OPEN</code> · <code>POPOUT.CLOSE</code></p><p><strong>判据</strong>：<code>canChange</code> · <code>canPopout</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSideNav</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td>选中的叶子；尚未选中为 null。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>collapsed</code></td><td><code>boolean</code></td><td>折叠成图标栏；顶层分支改为浮层弹出子级面板。</td></tr><tr><td><code>popoutValue</code></td><td><code>string | null</code></td><td>折叠态下正弹出子级面板的顶层分支；没弹出为 null。</td></tr><tr><td><code>openPopout</code></td><td><code>(value: string) =&gt; void</code></td><td>弹出某顶层分支的子级面板（仅折叠态有效）。</td></tr><tr><td><code>closePopout</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>roving tabindex 的锚点；无可见锚点为 null。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isExpanded</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isActiveBranch</code></td><td><code>(value: string) =&gt; boolean</code></td><td>选中项的祖先分支：展开高亮「当前所在的那一枝」。</td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>setExpandedValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>expand</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>collapse</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>叶子行的列表项容器：链接与分支一样是列表的一条，作者把 link 裹在它里面。</td></tr><tr><td><code>getGroupProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupLabelProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTriggerProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBranchTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>行文字的载体：折叠成图标栏时由皮肤整个藏掉，不会裁出半个字。</td></tr><tr><td><code>getBranchIndicatorProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>isPopoutPanel</code></td><td><code>(value: string) =&gt; boolean</code></td><td>该分支在折叠态下是否以浮层面板出现；决定作者要不要渲染定位层。</td></tr><tr><td><code>getPopoutPositionerProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td>弹出面板的定位层。吃引擎坐标、承载层号，作者须把它搬到浮层落点， 免得祖先的层叠上下文把面板困住。非弹出分支不渲染这一层。</td></tr><tr><td><code>getBranchContentProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLinkProps</code></td><td><code>(props: SideNavNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLinkTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>链接文字的载体：折叠时由皮肤整个藏掉。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in branch-trigger</td><td>展开/收起该枝（原生按钮激活）</td></tr><tr><td><code>Enter</code></td><td>focus in link</td><td>激活链接（原生行为）并落选中</td></tr><tr><td><code>ArrowDown</code></td><td>focus in 行</td><td>下一可见行（roving tabindex）</td></tr><tr><td><code>ArrowUp</code></td><td>focus in 行</td><td>上一可见行</td></tr><tr><td><code>ArrowRight</code></td><td>focus in 收起的分支行</td><td>展开该枝；已展开时进第一个子行（RTL 与 ArrowLeft 对调）</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in 展开的分支行</td><td>收起该枝；叶子或已收起时回父分支（RTL 与 ArrowRight 对调）</td></tr><tr><td><code>Home</code></td><td>focus in 行</td><td>第一可见行</td></tr><tr><td><code>End</code></td><td>focus in 行</td><td>最后一可见行</td></tr><tr><td><code>ArrowRight</code> / <code>Enter</code> / <code>Space</code></td><td>focus in 折叠态顶层分支行</td><td>弹出子级面板并落焦第一行（RTL 与 ArrowLeft 对调）</td></tr><tr><td><code>ArrowLeft</code> / <code>Escape</code></td><td>focus in 弹出面板</td><td>收回面板，焦点还给触发按钮（RTL 与 ArrowRight 对调；Escape 归消解层）</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>translations?.root</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;navigation&#39;</td></tr><tr><td><code>group</code></td><td><code>aria-labelledby</code></td><td><code>group-label</code> 部件的 id</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>branch-trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>branch-trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>branch-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>link</code></td><td><code>aria-current</code></td><td>&#39;page&#39; | undefined</td></tr><tr><td><code>link</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | undefined</td></tr></tbody></table><ul><li><code>list</code> 与 <code>branch-content</code> 是列表容器（<code>ul</code>），直接子节点只能是列表项：分支写 <code>branch</code>（<code>li</code>），叶子写 <code>item</code>（<code>li</code>）裹住 <code>link</code>（<code>a</code>）。链接直接挂在列表下会让列表语义作废。</li><li>行文字必须写进 <code>branch-text</code> / <code>link-text</code>。折叠成图标栏时这段文字被裁到看不见但仍参与播报，它就是按钮与链接在图标栏里唯一的可及名；行里只放图标不写文字，折叠后读屏报不出这一项是什么。</li><li>行里的图标是装饰，写 <code>aria-hidden=&quot;true&quot;</code>，别让它挤进可及名。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/side-nav.css</code> 按部件选择：<code>[data-scope=&quot;side-nav&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>list</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>group-label</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch</code></td><td><code>data-in-path</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch-trigger</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch-trigger</code></td><td><code>data-in-path</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch-trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-trigger</code></td><td><code>data-value</code></td><td>itemValue(el)</td></tr><tr><td><code>branch-indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>data-popout</code></td><td>&#39;&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>link</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>link</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>link</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>link</code></td><td><code>data-value</code></td><td>itemValue(el)</td></tr><tr><td><code>popout-positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>popout-positioner</code></td><td><code>data-placement</code></td><td>placed?.placement</td></tr><tr><td><code>popout-positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>popout-positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-side-nav-collapsed-w</code> · <code>--xh-side-nav-fg</code> · <code>--xh-side-nav-gap</code> · <code>--xh-side-nav-group-label-px</code> · <code>--xh-side-nav-group-label-py</code> · <code>--xh-side-nav-icon-size</code> · <code>--xh-side-nav-indent</code> · <code>--xh-side-nav-link-gap</code> · <code>--xh-side-nav-link-px</code> · <code>--xh-side-nav-link-radius</code> · <code>--xh-side-nav-p</code> · <code>--xh-side-nav-popout-bg</code> · <code>--xh-side-nav-popout-border</code> · <code>--xh-side-nav-popout-layer</code> · <code>--xh-side-nav-popout-max-h</code> · <code>--xh-side-nav-popout-max-w</code> · <code>--xh-side-nav-popout-min-w</code> · <code>--xh-side-nav-popout-p</code> · <code>--xh-side-nav-popout-radius</code> · <code>--xh-side-nav-popout-shadow</code> · <code>--xh-side-nav-row-bg-hover</code> · <code>--xh-side-nav-w</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./layout">布局</a>的 <code>sider</code>，折叠开关接布局的折叠态。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>层级压到两级，第三级开始用户就记不住路径了。</li><li>折叠态一定要留 <code>collapsedPopout</code>，否则图标栏进不去子级。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把每个叶子都做成分支（点开只有一项）。</li><li>折叠时把整棵树卸载：展开状态与滚动位置全丢。</li></ul>',49))])}const N=i(h,[["render",u]]);export{f as __pageData,N as default};
